```cpp
#include <iostream>
#include <string>
using namespace std;

bool can_make_abc(string s) {
    if (s == "abc" || s == "acb" || s == "bac" || s == "cba")
        return true;
    return false;
}

int main() {
    int t;
    string s;
    cin >> t;
    while (t--) {
        cin >> s;
        if (can_make_abc(s))
            cout << "YES" << endl;
        else
            cout << "NO" << endl;
    }
    return 0;
}
```

